ITEMS = [
 S("txt-p77-t0200", 77, "Chapter 4: Referral and Linkages > 4.1 Introduction", "4.1 Introduction", [], "Key message: HIV referral and linkages is a critical component of prevention and treatment programs aimed at i si i ou ’s o o a ds a i i lo al a a d p io a s o all population groups.\nKey message: Delays in starting ART can have adverse effects, especially for infants, people with TB or advanced immunosuppression who are at high risk of death."),
 S("txt-p78-t0201", 78, "Chapter 4: Referral and Linkages > 4.2 Definition of Key Terms", "4.2 Definition of Key Terms", ["0179", "0180", "0182", "0184"], "∞ Clients referred from community to facility must be referred using a comprehensively filled referral form and the health care worker referring the client has the responsibility to make a follow-up to determine if the client was linked for the services. ∞ A package of support interventions should be offered to ensure timely linkage to care for all PLHIV and linkage to prevention services for those testing HIV-negative yet at risk of getting infected.\nThe process of referral and linkages begins with demand creation for HIV testing, and HIV diagnosis and ends with enrolment in prevention, care or treatment and other health services:"),
 S("txt-p80-t0202", 80, "Chapter 4: Referral and Linkages > 4.3 Responsibilities of HCW at the different stages of the referral and linkage process (continued)", "4.3 Responsibilities of HCW at the different stages of the referral and linkage process (continued)", [], "Key message: Before a client is referred for ART services, the HTS service provider must ascertain if the client is a genuinely new positive or is returning to care."),
 S("txt-p80-t0203", 80, "Chapter 4: Referral and Linkages > 4.4 Principles of Linkage", "4.4 Principles of Linkage", ["0187", "0188", "0189", "0190"], "∞ ART initiation should adhere to the overarching ethics of providing a client-centred approach, that is providing care that focuses on the needs, preferences, and expectations of the individuals. ∞ Linkages should uphold individual dignity and respect, especially for the vulnerable subpopulations ∞ Linkages should promote the engagement and support of people and families to play an active role in their care through informed decision-making. ∞ All people newly diagnosed with HIV should be retested to verify their HIV status before starting ART ( see HTS chapter 3 ) ∞ Test and start should be provided to all clients living with HIV regardless of CD4 cell count, ∞ Clients with no contraindication to rapid ART initiation should be fully informed of the benefits of ART and offered rapid ART initiation, including the option of same-day initiation."),
 S("txt-p81-t0204", 81, "Chapter 4: Referral and Linkages > 4.6 Interventions to improve HIV linkages for PLHIV", "4.6 Interventions to improve HIV linkages for PLHIV", [], "A client with an HIV positive result should be timeously provided with a package of supportive interventions. The following interventions should be provided to improve linkages and engagement in care:"),
 S("txt-p81-t0205", 81, "Chapter 4: Referral and Linkages > 4.7 Linkage to prevention services", "4.7 Linkage to prevention services", [], "Clients testing HIV-negative yet at risk of getting infected with HIV must be linked to prevention services while those testing HIV positive must be linked to treatment services or positive should be"),
 S("txt-p81-t0206", 81, "Chapter 4: Referral and Linkages > 4.8 Linkages to treatment services", "4.8 Linkages to treatment services", ["0191"], "HIV linkages can be done within the facility, between facilities, from community to facility or from facility to community Bidirectional communication between facilities and communities is important to improve HIV linkages. ∞ For collaboration to be smooth, HIV Community testing partners should participate in facility multi-disciplinary meetings."),
 S("txt-p81-t0207", 81, "Chapter 4: Referral and Linkages > 4.9 Types of linkage services", "4.9 Types of linkage services", ["0192"], "HIV linkages can be done within the facility, between facilities, community to facility or facility to the community - Bidirectional communication between facilities and communities is important to improve HIV linkages. ∞ For collaboration to be smooth, HIV Community testing partners should participate in facility multi-disciplinary meetings."),
 S("txt-p82-t0208", 82, "Chapter 4: Referral and Linkages > 4.10 Summary of enhanced Linkages Case Management", "4.10 Summary of enhanced Linkages Case Management", ["0196"], "Patient literacy and ART readiness assessment are integral interventions to retain clients in care and should be done at each clinical visit."),
 S("txt-p83-t0209", 83, "Chapter 4: Referral and Linkages > 4.11 Clients returning to care", "4.11 Clients returning to care", ["0199", "0201"], "Any clients who return to the facility either of their own accord or after tracing, more than 28 days after missing an appointment are said to be returning to care. Clients should be provided with the returning to care package as indicated in the enhanced LCM SOP enhanced SOP (pages 62-67 ) . Clients must be actively followed up in all stages to bring them back to care. There are different stages of treatment interrupters, which are:\n▪ immediate (<28-day post-initiation)\n▪ early interrupters (>28 days <6 months) and,\n▪ late interrupters (+6 months)."),
 S("txt-p85-t0210", 85, "Chapter 5: Basic Care Package for HIV-Positive Individuals > Introduction", "Introduction", ["0202", "0203"], "All clients who test HIV-positive should be linked to and enrolled on HIV chronic care on the same day of diagnosis. All health facilities should provide the basic HIV chronic care package as defined in this chapter.\nThe basic HIV chronic care package for people living with HIV (PLHIV) includes:\n- Initial clinical evaluation and categorization of clients.\n- Opportunistic infection screening and management, including the provision of prophylactic\n- Adherence and psychosocial support services.\n- Patient Education\n- HIV index testing.\n- Linkage to care and treatment\n- Laboratory tests.\n- Routine and structured clinical follow-up visits.\n- Integration of HIV services with other health services such as\n   - TB\n   - Sexual and reproductive health i.e., family planning and cervical cancer screening and management\n   - HIV prevention services including the provision of condoms and STI screening and management\n   - Hepatitis B screening and management\n   - Non-communicable disease screening and management\n   - Mental health screening and management\n   - Palliative care\n   - Nutritional assessment\n   - Immunisation\nThe basic HIV chronic care package should be differentiated based on the client’s laboratory and clinical evaluation findings. See Table 5.2 for definitions of relevant categories.\nPharmacovigilance is also an integral part of HIV service delivery. All adverse events should be reported to the National pharmacovigilance Centre. These include adverse events from all the medical products a patient on ART patient is taking. See Section 5.12\nKey message: Clients returning into HIV care after disengaging from care should be fully assessed and provided adequate adherence support in order to retain them in HIV chronic care. ART should be (re)initiated from the entry point where the patient tests positive from, then referred to the ART clinic for follow-up. This ensures that patients are not lost while navigating the health facility departments. See Section 13.1 in eLCM SOPs"),
 S("txt-p86-t0211", 86, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.1 Assessment of PLHIV at Initial Contact", "5.1 Assessment of PLHIV at Initial Contact", ["0204", "0206", "0207"], "PLHIV present at different stages of disease progression. Upon presentation, clients should be assessed using baseline CD4 count, and clinical evaluation, including WHO clinical stage to determine whether the client has mild, moderate, or advanced immunodeficiency. See Table 5.7 for definitions of mild, moderate and severe immunodeficiency. Clients must be offered differentiated service delivery according to their clinical presentation. For differentiated service delivery for clients on ART, Section 5.7"),
 S("txt-p88-t0212", 88, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.2 Baseline Laboratory Evaluation of PLHIV", "5.2 Baseline Laboratory Evaluation of PLHIV", ["0209", "0211", "0212"], "Baseline laboratory investigations are essential components of assessing clients for the start or restart of HIV chronic care.\nKey message: Baseline laboratory samples should be collected on the same day as the HIV diagnosis although absence of results should not delay ART initiation."),
 S("txt-p90-t0213", 90, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.3 Changing Role of CD4", "5.3 Changing Role of CD4", ["0215", "0217"], "Prioritise CD4 testing for new ART patients, suspected treatment failures and those re-engaging to care after treatment interruption >1 year For clients who initiate ART with a baseline CD4 count >350cell/mm³, and show good clinical response, there is no value added by doing a follow-up CD4 count at 6 and 12 months For clients who initiate ART with a CD4 count <350cell/mm³, CD4 monitoring should be done 6 and 12 months after ART initiation. Once the client has two consecutive undetectable viral loads CD4 monitoring can be stopped. If treatment failure is suspected, resume CD4 monitoring until the client has an undetectable viral load.\nKey message: CD4 remains a valua le la oratory test that is used to determine a client’s chance of developing opportunistic infections. However, clients stable on ART with undetectable viral load and CD4 count ≥350 cells/mm ³ do not require routine CD4 count monitoring.\nAn individual’s CD4 count determines the following:\n- Immune status at enrolment (e.g., mild, moderate or advanced immunodeficiency)\n- Immune status for clients on ART with viral load (VL) ≥1000 copies/mL and failing treatment or clients returning to care after a long interruption in treatment e.g., a year\n- Evaluating the need for routine screening of opportunistic infection\n   - If CD4 ≤100 cells/mm³, then do LF CrAg screening should be completed\n- If CTX prophylaxis should be started, stopped or restarted\n- Disease progression, for clients with HIV who have not initiated antiretroviral therapy (ART) See Annex 11.26 for the use of CD4 and VL tests."),
 S("txt-p90-t0214", 90, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.4 Co-trimoxazole Preventive Therapy (CPT)", "5.4 Co-trimoxazole Preventive Therapy (CPT)", ["0216"], "CPT is used to prevent the following common opportunistic infections among PLHIV:\n- Pneumocystis jirovecii pneumonia (PCP)\n- Toxoplasmosis\n- Diarrhoea caused by Isospora belli and Cyclospora species\n- Certain bacterial infections, including bacterial pneumonia and urinary tract infections\n- Also useful in Malaria endemic areas"),
 S("txt-p90-t0215", 90, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.4 Co-trimoxazole Preventive Therapy (CPT) > CPT Indications", "CPT Indications", [], "- Adults and adolescents (including pregnant women) with severe or advanced HIV clinical disease (WHO stage 3 or 4)\n- Adults (including pregnant women) with CD4 cell count ≤350 cells/mmᵌ\n- All people living with HIV with active TB disease regardless of CD4 cell count\n- All children < 5 years old diagnosed with HIV"),
 S("txt-p91-t0216", 91, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.4 Co-trimoxazole Preventive Therapy (CPT) > When to start CPT", "When to start CPT", [], "CPT should be started at enrolment into HIV chronic care. Clients with active TB — adults, adolescents and children — should continue to receive CPT regardless of CD4 count, until completion of TB treatment. After TB treatment is completed, they can be assessed to determine if CPT can be stopped."),
 S("txt-p91-t0217", 91, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.4 Co-trimoxazole Preventive Therapy (CPT) > Cotrimoxazole Dosing", "Cotrimoxazole Dosing", ["0218"], "Key message: Clients with a history of severe allergy to sulphur should not be given CPT. In such cases, dapsone is a safer alternative."),
 S("txt-p91-t0218", 91, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.4 Co-trimoxazole Preventive Therapy (CPT) > Cotrimoxazole adverse events (continued)", "Cotrimoxazole adverse events (continued)", [], "Toxicity Level Grade 1\nGrade 2\nGrade 3\nGrade 4\nKey message: Document any allergic reactions clearly in the client’s file and appointment card, and report through available pharmacovigilance tools ("),
 S("txt-p91-t0219", 91, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.4 Co-trimoxazole Preventive Therapy (CPT) > Cotrimoxazole adverse events (continued)", "Cotrimoxazole adverse events (continued)", [], "Key message: )."),
 S("txt-p92-t0220", 92, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.4 Co-trimoxazole Preventive Therapy (CPT) > When to stop CPT", "When to stop CPT", ["0221", "0222"], "Continue CD4 monitoring as per viral load schedule while a client remains on CPT. Clients should continue CPT until the following occurs:\n- The client has full immune recovery evidenced by an undetectable viral load, or if VL is unavailable, at least one CD4 counts >200 cells/mm³ for clients above 5 years of age and >350 cells/mm³ for children 3-5 years\n- no history of PJP or toxoplasmosis or other opportunistic infections.\n- Severe (Grade 3 or 4) adverse reaction to CPT or any other sulphur-containing medication.\n- Severe kidney disease (creatinine clearance <50 mL/min)\n- Severe liver disease (aspartate aminotransferase/ alanine aminotransferase [AST/ALT] >5 times the upper limit of normal)\n- There is no history of PJP or toxoplasmosis.\nThe reason for stopping CPT should be documented in the client’s file and appointment card. If CPT must be permanently discontinued due to an allergic reaction, dapsone is an acceptable alternative\nKey message: Recommended Dapsone done:Adults and adolescents: 100mg po od with foodChildren: 2mg/kg od"),
 S("txt-p92-t0221", 92, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.5 Co-trimoxazole desensitization in adults and adolescents (continued)", "5.5 Co-trimoxazole desensitization in adults and adolescents (continued)", [], "*The Co-trimoxazole oral suspension is (200 mg SMZ + 40 mg TMZ) / 5 ml"),
 S("txt-p93-t0222", 93, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.6 ART initiation", "5.6 ART initiation", ["0225"], "All PLHIV are eligible for rapid ART initiation (within 7 days of HIV diagnosis) regardless of CD4 count or WHO clinical stage ( except for clients with cryptococcal or TB meningitis). The following priority populations should be evaluated urgently and offered rapid ART initiation as they are at risk of poor outcomes:\n- Clients with advanced immunodeficiency (CD4 ≤200 cells/mm³ or WHO clinical stage 3 or 4). ART should be delayed only when meningitis or another central nervous system infection is s uspected Infants and young children ≤5 years old\n- Pregnant and breastfeeding women\n- Clients with Tuberculosis (TB)\n- HIV-positive individuals in sero-different relationships\n- Clients with hepatitis B virus (HBV) coinfection\n- Clients with HIV-associated nephropathy\nKey message: Among PLHIV with signs and symptoms suggesting TB, except for TB meningitis, initiate ART while rapidly investigating for TB, with close follow-up within seven days to initiate TB treatment if TB is confirmed"),
 S("txt-p93-t0223", 93, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.6 ART initiation > Clients returning to care", "Clients returning to care", ["0226"], "All clients returning to care should be evaluated for AHD and offered rapid ART initiation; delay ART initiation only if the client has TB meningitis and/or cryptococcal meningitis."),
 S("txt-p93-t0224", 93, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.6.1 Community ART initiation", "5.6.1 Community ART initiation", ["0227", "0228"], "Rapid ART initiation should be prioritised for all eligible clients. To provide patient-centred care while improving linkage to ART services, ART initiation may be offered in the community. Community ART initiation will be implemented following these guiding principles:\n- Only where the team has a trained clinician to offer the ART readiness assessment, pre-ART counselling and ART initiation\n- The client should be willing to be linked to a health facility of their choice and should be able to attend a clinical visit at the health facility within 2 weeks of community ART initiation. There is a need to integrate the implementation of the basic package of care either in the community or at the 2-week visit at the facility to identify AHD, especially to acquire a baseline CD4. Refer to Table 5.7 and Table 5.7 for the package of care for stable clients\n- The client is clinically well, with WHO clinical stage 1 or 2, AND has no signs and symptoms of OIs or any comorbidities that may require further assessment or investigations. It is recommended that these patients get the required information and get benefits from same-day or rapid initiation within 7 days.\n- For clients returning to care presenting with the old medical record, there must be no history of treatment failure, or current immunological or clinical failure. As clients who disengaged from care are at risk of interrupting treatment again, there must be an emphasis on a plan for psychosocial support to foster retention for all treatment interrupters with the involvement of treatment supporters, community support structure etc. If these principles are not met the client should be referred to the nearest health facility for assessment and ART initiation and not be initiated within the community."),
 S("txt-p94-t0225", 94, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.7 Differentiated service delivery (DSD)", "5.7 Differentiated service delivery (DSD)", ["0229"], "Differentiated service delivery, previously referred to as differentiated care, is a person-centred approach that simplifies and adapts HIV services across the cascade in ways that both serve the needs of people living with and vulnerable to HIV and optimize available resources in health systems. The principles of differentiated service delivery can be applied to prevention, testing, linkage to care, ART initiation and follow-up and integration of HIV care and coinfections and comorbidities. Differentiated service delivery for HIV treatment has become a critical component of recognizing the diversity of needs of people living with HIV (WHO, 2021)."),
 S("txt-p94-t0226", 94, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.7.1 Differentiated service delivery in HIV prevention, testing and linkages", "5.7.1 Differentiated service delivery in HIV prevention, testing and linkages", ["0230", "0231"], "To reach the remaining people living with HIV who do not yet know their status the principles of differentiated service delivery will help identify service gaps and adapt HTS services to client needs. The aim is to provide a systematic approach that will consider the core components of the first 95: mobilizing, testing and linking to prevention and/or treatment. DSD simplifies and adapts HIV services across the HTS cascade, to reflect the preferences and expectations of various groups of PLHIV, while reducing unnecessary burdens on the health system. It supports shifting resources to clients; who are most in need and hence, in the context of HIV testing, is aimed at developing HIV testing strategies, targeted at identifying those PLHIV who do not yet know their status, to link them to HIV care and identifying people who need and want HIV prevention services, including PrEP, to link them to these services.\nWhen described as a service delivery model for HTS, these three components (mobilizing, testing and linking) are necessary and should be included in the design of the model. Alongside the core components, the DSD model shall use building blocks as a foundation of HTS DSD. These are:\n- What services are provided (the package of services)?\n- Where are HIV testing services delivered (location of mobilizing, testing and linking)?\n- When are HIV testing services delivered (time of day and frequency of mobilizing, testing and linking)?\n- Who is providing HIV testing services (the cadres performing the mobilizing, testing and linking)?\nHIV programs require strong linkages between testing, prevention, clinical care, and social support services, which are often delivered by different providers working in diverse locations that range from communities to Health facilities. Following an HIV-negative result, the client should receive information about HIV prevention strategies, including PrEP, and if the client desires, linked to PrEP services, preferably at the same location and/or on the same day. PrEP should be offered as an additional prevention choice for people at substantial risk of HIV infection, as part of a combination of prevention approaches that include HTS services, risk reduction counselling, diagnosis and treatment of STIs, male and female condoms, lubricants, ART for all HIV-positive people, and VMMC. PrEP, including all current and introduced methods, can be offered in and outside of healthcare facilities to meet the needs of HIV-negative clients who need and want HIV biomedical prevention."),
 S("txt-p95-t0227", 95, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.7.2 Differentiated service delivery in HIV care and treatment", "5.7.2 Differentiated service delivery in HIV care and treatment", ["0232"], "- Long-term care and adherence should be promoted by allowing clients with undetectable VL to choose models of care that best suit their needs when accessing ART services. Differentiated ART Service Delivery (DSD) models seek to :\n- Empower clients to actively participate in their care\n- Reduce client-related costs of accessing care\n- Allow equitable service allocation as determined by individual client category needs\n- Supporting clients to achieve and maintain viral load suppression (VLS) by facilitating retention in care” (providing models adapted to clients’ needs supports retention in care and subsequently VLS.\n- Keep clients motivated to remain in care by ensuring clients have an undetectable viral load\n- Improve adherence through population-specific care in the treatment delivery Further guidance is provided through the updated DSD guidelines\nHIV care should be differentiated according to clinical evaluation, laboratory evaluation and client needs. This approach will ensure that services are client- centred address the client’s needs and expectations and improve efficiencies a s well as client outcomes. Care packages for stable clients should also be defined whether at the facility or community. Priority patients can be provided with 3-6 multi-month dispensing (MMD) of treatment where appropriate, recognizing their specific needs – paediatric patients require growth monitoring; KPs need STI screening per guidelines; HEI need immunization visits to be synchronised with mother’s, most of who have been stable on ART etc"),
 S("txt-p95-t0228", 95, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.7.3 Multimonth Dispensing (MMD)", "5.7.3 Multimonth Dispensing (MMD)", ["0233"], "PLHIV on ART for at least 6 months with an undetectable viral load and who are clinically well on ART are eligible for up to three months of refills (3MMD). The definition of being established on ART (stability) should be applied to all populations, after resolving any acute issues, including the following:\n- receiving antiretroviral therapy (ART) for at least 12 months;\n- have no current illness, which does not include well-controlled chronic health conditions;\n- a good understanding of lifelong adherence and\n- demonstrate evidence of treatment success with at least one suppressed viral load result within the past six months."),
 S("txt-p96-t0229", 96, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.7.3 Multimonth Dispensing (MMD) (continued)", "5.7.3 Multimonth Dispensing (MMD) (continued)", ["0235", "0238", "0243"], "The populations mentioned above for MMD, often represent specific cohorts in which retention and suppression of viral loads have been challenging and may benefit more from differentiated service delivery for HIV treatment models adapted to their needs.\nMulti-month refills and dispensing may be used alone or within any of the categories of differentiated service delivery for HIV treatment, each of which provides additional benefits to both the health system and clients. Multi-month refills may also be used for children older than two years since the dosage is adjusted less frequently beyond that age. Only children 2 – 5 years with consistent, knowledgeable and committed caregivers are eligible for multi-month refills up to 3MMD See Chapter 9 Section 9.16 for more information on DSD in children."),
 S("txt-p100-t0230", 100, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.7.6 Available DSD Care Models for Clients on ART", "5.7.6 Available DSD Care Models for Clients on ART", ["0246", "0248"], "After 1 year on ART, clinically well clients who are considered established in care should be offered an opportunity to choose one of the less intensive different ART service delivery models to enhance their adherence. Clients not established in care should be offered more intensive DSD models at facilities. Established in care clients are free to switch from model to model for as long as they are eligible for the model of delivery chosen."),
 S("txt-p100-t0231", 100, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.7.6 Available DSD Care Models for Clients on ART (continued)", "5.7.6 Available DSD Care Models for Clients on ART (continued)", [], "Stable adult clients who are considered established on ART and eligible for less intensive DSD models may choose any of the less intensive models listed below."),
 S("txt-p101-t0232", 101, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.7.6 Available DSD Care Models for Clients on ART (continued)", "5.7.6 Available DSD Care Models for Clients on ART (continued)", ["0250"], "Refer to DSD guidelines for more details on the different DSD models available in the country.\nKey message: Assessment for DSD eligibility and client preference for ART dispensation (quantity of drugs and preferred DSD model) has to be done at each clinical visit. HCWs should assess whether the client still fits in the DSD model or should be enrolled in a different DSD model or needs to go back to the mainstreamcare"),
 S("txt-p101-t0233", 101, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.8 Prevention, Screening and Management of COVID-19 and other Common Opportunistic Infections", "5.8 Prevention, Screening and Management of COVID-19 and other Common Opportunistic Infections", ["0251"], "All PLHIV should be screened for opportunistic infections and treated appropriately. Common opportunistic infections among HIV clients, especially clients in Eswatini with advanced immunodeficiency (advanced disease), include TB, cryptococcal meningitis, PJP, Kaposi sarcoma, cervical cancer, recurrent bacterial pneumonia, recurrent oral candidiasis, oesophageal candidiasis, herpes zoster and toxoplasmosis.\nFor detailed management of opportunistic infections not covered in these guidelines, please refer to the Eswatini Standard Treatment Guidelines."),
 S("txt-p101-t0234", 101, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.8.1 COVID-19", "5.8.1 COVID-19", ["0252", "0253"], "Key message: In a publication by the WHO, HIV appeared to be a significant independent risk factor for severe or critical illness at hospital admission and in-hospital mortality. The increased risk associated with HIV infection means that PLHIV should be prioritised for vaccination campaigns\nThe risk of poor outcomes is higher in PLHIV with COVI-19, particularly if they also have other comorbid conditions like hypertension, diabetes mellitus, obesity, TB, and chronic kidney and liver disease.\n- Health care workers should counsel patients on the importance of maintaining an undetectable VL as well as managing comorbid conditions.\n- Unvaccinated patients should be continuously encouraged to register for and receive full vaccination at their nearest vaccination centre.\n- Patients should be educated not to go for vaccination when they suspect having COVID-19 symptoms but rather after the resolution of symptoms. Clients who previously tested positive for SARS-Cov-2 are encouraged to seek medical review. Refer to COVID-19 case management guidelines for more information\n- Infection prevention measures of wearing face masks, hand washing, social distancing and cough etiquette among others should be emphasised in all PLHIV.\nKey message: Some diseases present with similar symptoms to COVID-19. For patients presenting with COVID-19 like symptoms, HCWs should look out for other differentials e.g., TB, Malaria and manage them accordingly as they may be a contributing factor to morbidity and mortality. Vaccinated PLHIV should be encouraged to report vaccine adverse events through the toll-free number “ 977 ” .\nSteroids are known immunosuppressants which have drug interactions with some ARVs. However, dexamethasone used in COVID-19 patients with severe respiratory distress syndrome is given over a short duration and does not warrant dose adjustment of EFV, PIs and DTG. Conversely, EFV may decrease dexamethasone concentrations, and doubling the dexamethasone dose is therefore recommended. No drug-drug interactions are expected between ARV drugs and the COVID-19 vaccines.", pages=[101, 102]),
 S("txt-p102-t0235", 102, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.9 Basic package of care for children and adolescents living with HIV", "5.9 Basic package of care for children and adolescents living with HIV", ["0254"], "The overall goals of care for the HIV-infected child are the same as those for all other children; maintaining good health and preventing disease as well as support for the child/adolescent and the family. This can be achieved by providing comprehensive history, physical examination, lab investigation, general medical care and treatment of intercurrent illnesses should be conducted as summarised in the table below."),
 S("txt-p104-t0236", 104, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.9 Basic package of care for children and adolescents living with HIV > General medical care, prophylaxis and treatment of opportunistic infections and intercurrent illnesses", "General medical care, prophylaxis and treatment of opportunistic infections and intercurrent illnesses", ["0258", "0259", "0260", "0262"], "- CALHIV should be provided general/ emergency care prophylaxis and treatment of opportunistic infections and intercurrent illnesses\n- Children should initiate LTBI treatment\n   - within 1 month on ART (after TB is ruled out),\n   - on the day of TB treatment completion,\n   - if <12 months and with a history of TB contact\n- For fluconazole prophylaxis see section 6.2 Note: After a baseline clinical evaluation has been completed utilizing a thorough history and clinical examination, the client’s WHO clinical stage can be determined to further understand the severity of the client’s clinical condition and the associated ris k of mortality and determine the urgency of ART initiation and the follow-up requirements. Children with advanced HIV disease (AHD) require more frequent clinical reviews.\nTreatment of HIV infection\n- All CALHIV should be offered same-day initiation and when not possible, rapid ART initiation (as soon as the patient is ready, preferably within 2 weeks)\n- Opportunistic infection screening, treatment and Prophylaxis\n- Children with HIV present commonly for evaluation and treatment of illness. The integrated approach to the management of childhood illness remains the most effective method for managing sick children.\n- The risk of opportunistic infections correlates with the degree of immunosuppression. CD4 is higher in infants than in older children and adults, with normal values declining over the first few years of life. The CD4% is relatively independent of age. It is recommended that both the CD4 and CD4% are monitored in children and the lower of the 2 values used to determine the degree of immunosuppression and decision making."),
 S("txt-p104-t0237", 104, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.9 Basic package of care for children and adolescents living with HIV > CDC immunologic classification of HIV infection in children < 13 years of age (continued)", "CDC immunologic classification of HIV infection in children < 13 years of age (continued)", ["0263"], "Common clinical conditions in CALHIV: Common clinical conditions associated with HIV include candidiasis, dermatitis and other skin conditions, diarrhoea, lower respiratory tract infections, septicaemia, otitis media, sinusitis and failure to thrive (growth failure).\nOral and dental conditions : Candidiasis and angular cheilitis, Gingivitis and stomatitis due to CMV, HSV, Dental carries, Lymphoma Dermatitis : Atopic and Seborrheic dermatitis, Eczema, Psoriasis, Drug eruptions, Viral warts, molluscum contagiosum Gastroenteritis : cryptosporidiosis, Isosporiasis, CMV, atypical mycobacteria and, HIV enteropathy Respiratory infections : Bacterial pneumonia, PCP, TB, LIP, Bronchiectasis, Viral pneumonitis Viral pneumonitis : Respiratory Syncytial Virus (RSV), parainfluenza virus, influenza virus, adenovirus, varicella, measles and CMV", pages=[104, 105]),
 S("txt-p105-t0238", 105, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.9 Basic package of care for children and adolescents living with HIV > Cycle of events leading to clinical deterioration and growth retardation in persistent diarrhoea", "Cycle of events leading to clinical deterioration and growth retardation in persistent diarrhoea", ["0264"], "Assess for dehydration and ensure good hydration in all cases. Children with persistent or chronic diarrhoea should be managed as inpatients and treatment depends on the specific cause of diarrhoea ( see Standard treatment guidelines )"),
 S("txt-p105-t0239", 105, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.9 Basic package of care for children and adolescents living with HIV > HIV encephalopathy", "HIV encephalopathy", ["0266"], "HIV infection of the brain interferes with the achievement of childhood milestones and may present as stasis, slowing or retardation of developmental milestones or localized damage. Management involves early ART initiation, referral to a neurologist and additional support with physical therapy and social workers."),
 S("txt-p105-t0240", 105, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.9.1 Growth monitoring", "5.9.1 Growth monitoring", ["0267"], "Growth is a predictor of improved health outcomes, potential metabolic complications of HIV infection and /or ART and survival. The growth, nutrition and metabolism of HIV-infected children is an important aspect of providing basic care as it is well recognized that HIV-infected children do not grow as well as HIV-negative children even with adequate virological control.\nAs HCWs conduct nutritional assessments, it is important to:\n- Take a history from the caregiver. Ask the type of feeding, appetite, age at which child was weaned and symptoms of underlying illness e.g., TB.\n- Conduct physic al examination including the child’s mid -arm circumference, weight and height (and from birth through to 2 years of age, head circumference).\n- Review the growth chart at each clinical assessment\n- The increased risk of malnutrition is due to several reasons including:\n- Decreased food intake due to anorexia associated with illness, oral ulcers, and oral thrush\n- Increased nutrient loss due to malabsorption, diarrhoea, HIV enteropathy\n- Increased metabolic rate because of infections, OIs and the HIV infection itself.", pages=[105, 106]),
 S("txt-p106-t0241", 106, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.9.1 Growth monitoring > Physical and neurological Development", "Physical and neurological Development", ["0268"], "Development is the progressive acquisition of new skills over time and reflects the integrity of the CNS. It involves the assessment of gross motor, fine motor, language and communication as well as adaptive and social functioning. Developmental delay is the failure to attain the appropriate milestones for a child’s age. Please note the developmental milestones ( appendix 11.30 )."),
 S("txt-p106-t0242", 106, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.9.1 Growth monitoring > Adolescent development", "Adolescent development", ["0270"], "Neurological delays can present as developmental delay, cognitive deficits, behavioural problems, psychiatric manifestations, and school failure in young children."),
 S("txt-p107-t0243", 107, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.9.2 Mental Health", "5.9.2 Mental Health", ["0272", "0273", "0274"], "- Children and adolescents are susceptible to psychological disturbances due to HIV itself and perceptions regarding HIV in their environment. Some of the most common psychological disturbances include depression and anxiety, internalized stigma, post-traumatic stress disorder, cognitive difficulties, perceived lack of social support, alcohol/drug addiction and suicide. Any of these can significantly interfere with a patient’s sense of well -being and adherence. It is important to assess all areas of the life of a child/ adolescent using SHADSS approaches (School, Home, Activities, Depression/Self-esteem, sexuality and safety).\n- All CALHIV should receive basic screening for depression and general mental health before initiating ART, annually and when adherence challenges are identified. This is particularly so for all CALHIV who previously interrupted treatment or have suspected/confirmed treatment failure.\n- CALHIV with mild depression should receive supportive counselling. Those with moderate-severe depression should be managed as per guidelines ( see chapter 10 section 10.6 ).\nPrevention of Other Infections through Immunizations and prophylaxis Prevention of Other Infections through Immunizations and prophylaxis significantly reduces the frequency of invasive infections. This should be started and completed according to the recommended schedule ( see national immunisation schedule ). See Annex 11.33"),
 S("txt-p107-t0244", 107, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.10.1 STIs in PLHIV", "5.10.1 STIs in PLHIV", ["0275"], "All PLHIV should be assessed for symptoms of STIs. Syphilis screening using Rapid diagnostic test (RDT) Treponema pallidum haemagglutination assay (TPHA) should be performed as a baseline investigation for all sexually active adults and adolescents living with HIV. Sexual partners of clients with STIs should be contacted and treated as well. Early diagnosis and effective\ntreatment of STIs can contribute significantly toward reduced HIV transmission. For more information, see the National STI Guidelines. Adolescents who have STIs are at a higher risk of acquiring HIV. The same biological and social factors that increase vulnerability to STIs also increase vulnerability to HIV infection.", pages=[107, 108]),
 S("txt-p109-t0245", 109, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.10.1 STIs in PLHIV > Management of STIs in PLHIV (continued)", "Management of STIs in PLHIV (continued)", ["0282"], "HIV testing services should be offered routinely for all clients with STIs. In some cases of STI/HIV coinfection, larger doses and/or longer treatment duration of the drugs may be required. Clients with STI/HIV coinfection should be followed regularly and for a longer duration. Excessive use of antimicrobials should be avoided. All clients with STIs should receive individual counselling on risk reduction and prevention of transmission to partners, together with the provision of commodities."),
 S("txt-p109-t0246", 109, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.10.1 STIs in PLHIV > STIs in Children and Adolescents", "STIs in Children and Adolescents", ["0276", "0283"], "Apart from neonatal infections and congenital syphilis, the occurrence of STIs in children and adolescents below 18 years of age invariably indicates sexual abuse. If identified, both emotional and legal support is recommended for the child as part of the comprehensive management of STIs in children and adolescents. Adolescents are not always empowered to negotiate for safe sex so should be screened and treated following the STI screening tool.\nIn rare instances, the following STIs may not indicate sexual abuse:\n- Chlamydial vaginitis, can be acquired perinatally and manifest up to the age of 3 years\n- Genital warts, unless supported by other evidence\n- Bacterial vaginitis alone\n- Candidiasis"),
 S("txt-p109-t0247", 109, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.10.2 Contraception", "5.10.2 Contraception", ["0280", "0284"], "Key message: Contraceptive needs, Pregnancy history, including the first day of the last normal menstrual period, should be documented at every visit.\nKey message: should be assessed and contraception offered to every HIV-positive woman at every visit.\nThe following contraceptive methods are offered in Eswatini:\n- Condoms (both male and female)\n- Oral contraceptives\n- Injectable contraceptives\n- Subdermal implants\n- Intrauterine contraceptive devices (IUCDs)\n   - Copper-bearing IUCDs, widely available in public health facilities\n   - Levonorgestrel-releasing IUCDs (Hormonal IUD), available in some private facilities\n- Tubal ligation - bilateral tubal ligation\n- Vasectomy\n- Natural methods\n   - Rhythm method/ Withdrawal method/Breastfeeding/Lactational amenorrhoea method\n   - Abstinence/ Outercourse\n   - Symptoms-based methods: Monitoring basal body temperature and cervical secretions\nKey message: If blood pressure is ≥ 160/100 mm Hg, do not provide COCs. Help her choose a method without oestrogen, but not a progestin-only injectable. Blood pressure measurement is desirable before starting a hormonal method. However, where the risks of pregnancy are high and few methods are available, a woman should not be denied a hormonal method simply because her blood pressure cannot be measured. If possible, she can have her blood pressure measured later at a time and place convenient for her.\nHormonal contraception can be taken by women who:\n- have varicose veins\n- have never conceived\n- have anaemia/have a history of anaemia\n- are over 40years of age\n- have just had an abortion, miscarriage, or ectopic pregnancy\nSome family planning methods are contraindicated with antiretroviral drugs (ARVs). See Annex 11.5 for interactions between ARVs and hormonal contraceptives.\nKey message: Due to drug-to-drug interactions, Jadelle should never be used with EFV PrEP can be taken safely with all family planning methods and can be used safely when breastfeeding\nFor additional information regarding family planning counselling, refer to National Family Planning Guidelines.", pages=[109, 110]),
 S("txt-p110-t0248", 110, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.11 Monitoring Clients Initiated on ART", "5.11 Monitoring Clients Initiated on ART", ["0285"], "All clients diagnosed with HIV should be assessed and managed according to the appropriately differentiated care package ( see Table 5.7 ). Clients are eligible to initiate ART regardless of CD4 count or WHO clinical stage and preferably within 7 days of HIV diagnosis. Same-day initiation is encouraged for clients who are ready to start ART; treatment literacy and empowerment of lifelong treatment should continue during the first few weeks/months of ART."),
 S("txt-p114-t0249", 114, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > What is Pharmacovigilance?", "What is Pharmacovigilance?", ["0292"], "Pharmacovigilance is defined as the science and activities concerned with the detection, assessment, understanding, and prevention of adverse reactions (ADR) to medicines (i.e., adverse drug reactions). The ultimate goal of this activity is to improve the safe and rational use of medicines, thereby improving the client's care and public health."),
 S("txt-p114-t0250", 114, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > What is an Adverse Event (AE)?", "What is an Adverse Event (AE)?", ["0293"], "Any unfavourable and unintended sign (including an abnormal laboratory finding, for example), symptom, or disease temporally associated with the use of a medicinal product, whether considered related to the medicinal product. Adverse events can be mild moderate or severe: they can also be serious. Adverse events can be mild, moderate or severe. Mild AEs : Awareness of signs or symptoms, but easily tolerated and are of minor irritant type causing no loss of time from normal activities. Symptoms do not require therapy or a medical evaluation; signs and symptoms are transient. Moderate AEs : Events introduce a low level of inconvenience or concern to the participant and may interfere with daily activities, but are usually improved by simple therapeutic measures; moderate experiences may cause some interference with functioning Severe AEs : Events interrupt the patient’s normal daily activities and generally require systemic drug therapy or other treatment; they are usually incapacitating. Serious Adverse Events (SAE) are defined as any untoward medical occurrence(s) that at any dose results in death, hospitalisation or prolongation of existing hospitalisation, persistent or significant disability/incapacity or a congenital anomaly or birth defect. Refer to the National Pharmacovigilance guideline for more information on adverse events. Severe AEs may not be SAEs: Severe AE ≠ Serious AE (SAE)\nKey message: Serious AEs must be reported to the national pharmacovigilance centre immediately within 24hours of occurance."),
 S("txt-p114-t0251", 114, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > What is an Adverse Drug Reaction (ADR)?", "What is an Adverse Drug Reaction (ADR)?", [], "ADRs are commonly defined as a response to a medicine that is noxious and unintended, including lack of efficacy, which occurs at any dosage and can also result from an overdose, misuse, or abuse of medicine."),
 S("txt-p114-t0252", 114, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > Spontaneous reporting", "Spontaneous reporting", ["0294"], "This is the primary method used in Eswatini. It is the main mechanism for passive surveillance used to generate signals/alerts of adverse events, which can then be investigated further. This method of reporting covers all medicinal products at all levels of health facilities in the country."),
 S("txt-p115-t0253", 115, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > Active PV reporting", "Active PV reporting", ["0295"], "An ongoing systematic collection, analysis, interpretation and dissemination of the client’s medicine sa fety data. It involves the systematic screening, recording and reporting of adverse events especially severe adverse events, serious adverse events (SAEs) and adverse effects of special interest (AESIs). All deaths are to be reported and as much relevant information on ascertainment of the cause of death should be consistently collected. Reporting of AEs and other events (e.g., pregnancy, lactation exposure) may be required, primarily based on what is known about the safety profile of the new agent and also for other possible harms which have not yet been described.\nKey message: All SAEs and Severe (Grade 3 or 4) AEs detected should be reported to the NPC within 24-48 hours using active PV reporting form or the WhatsApp number +268 7655 7303 ."),
 S("txt-p115-t0254", 115, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > Who should report AEs/ADRs?", "Who should report AEs/ADRs?", ["0296"], "All healthcare workers, including doctors, dentists, pharmacists, nurses, and other health professionals are required to report all suspected adverse reactions/events to medicines (including vaccines, X-ray contrast media, and traditional and herbal remedies), potentially serious or clinically significant. See Annex 11.27 Monitoring and reporting drug therapy problems — including adverse drug reactions and medication errors — should be an integral part of clinical practice for ensuring client safety and optimal treatment outcomes. Health care workers should alert clients to the potential of experiencing toxicities in their medication and advise clients on when to report to their healthcare providers."),
 S("txt-p115-t0255", 115, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > Importance of PV report", "Importance of PV report", ["0297"], "A well-completed AE/ product quality form submitted could result in any of the following: Additional investigations into the use of the medicine in Eswatini Educational initiatives to improve the safe use of the medicine Appropriate package insert changes Changes to treatment guidelines Removal of the medicine from the market"),
 S("txt-p115-t0256", 115, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > What types of reactions should be reported?", "What types of reactions should be reported?", ["0298"], "The following adverse events should be reported (even if you are not certain the medicine caused the event): All suspected AE/ADRs to medicine, whether serious/minor, unexpected or unusually severe reactions which also include:\n- Product Quality\n- Lack of efficacy\n- Treatment failure\n- All suspected ADRs associated with medicine errors\n- All serious reactions and interactions\n- All adverse reactions to traditional or herbal remedies\nWhat product quality problems should be reported?\n- Suspected contamination\n- Questionable stability\n- Defective components\n- Poor packaging or labelling\n- Therapeutic failures", pages=[115, 116]),
 S("txt-p116-t0257", 116, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > How can AE/ADRs be prevented from occurring?", "How can AE/ADRs be prevented from occurring?", [], "Some AE/ADRs are unavoidable and cannot be prevented. However, most AE/ADRs can be prevented by following the basic principles of rational use of medicines: patients receive medications appropriate to their clinical needs, in doses that meet their requirements, for an adequate time, and at the lowest cost to them and their community"),
 S("txt-p116-t0258", 116, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > How do you recognize ADRs and AEs in clients?", "How do you recognize ADRs and AEs in clients?", ["0299"], "Healthcare workers prescribing medicines including ART should collect information that includes client details (e.g., age, sex, weight), details on the drug (e.g., dose, duration of treatment), details on the suspected reaction or reactions (e.g., description of the event, seriousness, outcome), medical history of the client, and other concomitant medication that the client was taking. The following approach helps assess possible ADRs and AEs:\n- Take a proper history and do a proper examination of clients.\n- Establish time relationships between the adverse event and suspected medicine.\n- Carry out a thorough physical examination with appropriate laboratory investigations if necessary.\n- Effects of De-challenge and rechallenge should be determined.\n- Check the known pharmacology of the medicine.\n- Ensure that all identified are appropriately managed before reporting. Further guidance on PV shall be provided on the National Pharmacovigilance guideline."),
 S("txt-p116-t0259", 116, "Chapter 5: Basic Care Package for HIV-Positive Individuals > 5.12 Pharmacovigilance in ART > How are adverse drug events/reactions reported?", "How are adverse drug events/reactions reported?", [], "An adverse drug event/reaction/product quality report form is provided on paper and should be completed in as much detail as possible before submitting it to the Pharmacy department through their monthly orders to the national pharmacovigilance centre (NPC) at the Central Medical Stores. Alternatively reporting forms can be sent to the NPC WhatsApp number +268 7655 7303\nKey message: 6 TB/HIV COLLABORATIVE ACTIVITIES & ADVANCED HIV\nKey message: DISEASE\nThe chapter gives guidance on the prevention, screening and management of tuberculosis (TB), advanced HIV disease (AHD) and Histoplasmosis among PLHIV", pages=[116, 117, 118]),
 S("txt-p118-t0260", 118, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.1 Introduction", "6.1.1 Introduction", ["0300"], "Tuberculosis is an infectious disease caused by Mycobacterium tuberculosis (MTB) bacilli. It is the leading cause of death among people living with HIV (PLHIV), accounting for about a third (512 000) of all global HIV-associated deaths in 2019. PLHIV are 20 times more likely to progress from latent TB infection to active TB compared to HIV-negative individuals, with a 10% annual risk for PLHIV and 5-10% lifetime risk for HIV-negative individuals. TB preventive treatment (TPT) is recommended for the treatment of latent TB infection (LTBI) in people at risk of progressing to active TB. TPT is known to reduce the risk of developing active TB by 60-90%, and to reduce mortality among PLHIV by 37% independent of ART."),
 S("txt-p118-t0261", 118, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.1 Introduction > TB/HIV collaborative activities", "TB/HIV collaborative activities", ["0301"], "Counselling on risk reduction behaviour to reduce the risk of TB transmission at home, in public and health facilities should be included in HIV care. Infection prevention in health facilities is the responsibility of the facility, including cough triage and management track for patients with cough and diagnosed TB. The following TB/HIV collaborative activities should be implemented at all entry points that provide HIV and TB care:"),
 S("txt-p119-t0262", 119, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.2 TB Screening > Systematic TB Screening among PLHIV", "Systematic TB Screening among PLHIV", ["0303"], "PLHIV should be systematically screened for TB disease using the WHO 4 symptoms screen (W4SS) tool at each clinical visit to a health facility. PLHIV are 15-22 times more likely to develop active TB disease compared to people without HIV, as such all efforts must be made to intensify systematic TB screening among this group. The national TB screening tool is recommended for screening PLHIV for TB."),
 S("txt-p119-t0263", 119, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.2 TB Screening > TB screening tests", "TB screening tests", ["0304"], "The following screening tests are recommended when available to improve sensitivity"),
 S("txt-p119-t0264", 119, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.2 TB Screening > TB screening tests (continued)", "TB screening tests (continued)", ["0306"], "Chest X-ray and C – reactive protein may be useful in improving the sensitivity of the four-symptom screen where feasible. The different TB screening algorithms are highlighted below.\nKey message: Due to limited capacity and access to radiograph services currently, the chest x-ray recommendation for screening may not be implemented until further notice!!", pages=[119, 120]),
 S("txt-p120-t0265", 120, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.3 TB Diagnosis", "6.1.3 TB Diagnosis", ["0308", "0310", "0312"], "Key message: All PLHIV who are TB presumptive should be evaluated for TB using TB LAM and Xpert MTB Rif (ultra).\nThe standard diagnostic tests for TB among PLHIV are Xpert MTB/RIF (Ultra)and LF urine LAM. Specimens from specific sites such as lymph nodes, and pleural fluid, may be obtained when extrapulmonary TB is suspected. Investigation to exclude drug-resistant TB should be done according to national TB treatment guidelines.\n- The use of LF urine LAM in TB diagnosis has been expanded to all PLHIV presumptive of TB as well as certain groups of patients with AHD as shown in Figure 6.1 below.\n- Clients with a positive TB LAM but no signs and symptoms of TB may require sputum induction for Xpert MTB/RIF (ultra). Note airborne transmission precautions should be observed in the setting of TB as well as COVID-19. The use and interpretation of the two tests in PLHIV, including advanced HIV disease in the diagnosis of TB, is shown in Figure 6.1 below;"),
 S("txt-p120-t0266", 120, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.3 TB Diagnosis > Children living with HIV", "Children living with HIV", ["0309"], "In children with signs and symptoms of TB, Xpert Ultra and LF LAM should be used as the initial diagnostic tests for TB rather than smear microscopy/culture and phenotypic drug susceptibility testing (DST). Investigations should be done to rule out TB drug resistance on sputum, nasopharyngeal aspirate, gastric aspirate or stool. Due to the difficulty in obtaining sputum specimens in children, sputum induction may be considered (see TB guidelines). Stool nasopharyngeal or gastric aspirates and urine specimens may be used as a complementary specimens for the diagnosis of TB in children."),
 S("txt-p120-t0267", 120, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.4 TB Treatment", "6.1.4 TB Treatment", [], "For more information on the diagnosis and management of TB, refer to the current National Tuberculosis Control Program Manual."),
 S("txt-p121-t0268", 121, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention", "6.1.5 TB Prevention", ["0313"], "- Latent TB is defined as a state of persistent immune response to stimulation by Mycobacterium tuberculosis with no evidence of clinically active TB disease. About a quarter of the world’s population is infected with TB. TPT for PLHIV is par t of the TB preventive treatment for people living with HIV. TPT used in combination with ART has been shown to benefit both TB prevention and mortality, even at higher CD4 cell counts.\n- The following are the recommended LTBI treatment (TPT) options in Eswatini;"),
 S("txt-p122-t0269", 122, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > Timing for TPT initiation", "Timing for TPT initiation", ["0315", "0316"], "Key message: TPT should be initiated 4 weeks after ART initiation . However, TPT initiation on the day of ART initiation may be considered, especially among stable clients without Advanced HIV Disease."),
 S("txt-p123-t0270", 123, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > Timing for TPT initiation (continued)", "Timing for TPT initiation (continued)", ["0318"], "Key message: Rifapentine is contraindicated in pregancy\nRefer to Section 9.8 for more information on TPT in children. TPT regimens and dosing by the population at risk are tabulated as follows:"),
 S("txt-p124-t0271", 124, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > Preventive treatment for Drug-Resistant TB", "Preventive treatment for Drug-Resistant TB", ["0321"], "Preventive treatment should only be considered for high-risk DR TB household contacts following a risk assessment Preventive treatment for multidrug-resistant TB requires a different regimen using a fluoroquinolone or other second-line agents as tabulated in the following table."),
 S("txt-p125-t0272", 125, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > Monitoring of TPT clients", "Monitoring of TPT clients", ["0324"], "Key message: TPT refill dates must be synchronized with ART refill or clinic visits"),
 S("txt-p125-t0273", 125, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > Management of TPT Adverse events", "Management of TPT Adverse events", ["0325"], "The following table presents the management of LTBI treatment adverse event"),
 S("txt-p126-t0274", 126, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > Management of TPT interruptions", "Management of TPT interruptions", ["0329"], "The management of TPT interruptions is important to ensure patients receive the required therapeutic doses. TPT should be completed within 6-9 months. 180 doses are required for effective preventive therapy. The following table shows the management of TPT interruptions according to the TPT regimen."),
 S("txt-p128-t0275", 128, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > TPT patient education", "TPT patient education", ["0334", "0335"], "Patient education and counselling are important in ensuring adherence to TPT Client health education and counselling The patient is educated on the following:\n- Basic facts and benefits of LTBI treatment and duration of therapy, dose, time etc.\n- Side effects of the treatment and reporting promptly to the health facility (e.g., yellowing of eyes, itchy skin rash, abdominal pain with vomiting) emphasize the effects of using traditional medicines, alcohol and drugs in combination with TB medication.\n- Importance of appointment keeping, adhering and completing treatment, assist the patient to choose one adherence aide such as cell phone, TV, calendar or radio reminders.\n- Importance of availability of support systems, getting to the clinic, taking medication, reminder strategies, storing medication)\n- The patient is assessed for any intentions to get pregnant and encouraged to report promptly should she have a plan to get pregnant Symptom awareness\n- All PLHIV should be educated on the importance of seeking medical care promptly if they or any person they live with develop signs and symptoms suggestive of active TB (e.g., any cough with blood-stained at times, chest pains, weakness, weight loss, fever, night sweats) Management of Household TB contacts\n- All household contacts of the TB patients regardless of bacteriological confirmation of the index case should be evaluated for TB and offered HIV testing and counselling. TPT should be offered to all eligible contacts who are HIV-positive or are children under 5 (regardless of HIV status) who do not have symptoms and signs suggestive of TB and children > 12 months living with HIV without active TB."),
 S("txt-p129-t0276", 129, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > TPT Outcomes", "TPT Outcomes", ["0336"], "Key message: Transferred out is no longer considered an outcome as it does not show the definitive outcome of a TPT initiation. It is the responsibility of the initiating facility to follow-up on all patients transferred out to document the outcome at the end of the TPT course."),
 S("txt-p129-t0277", 129, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > ART for TB patients", "ART for TB patients", ["0338", "0342"], "For clients who develop TB while taking ART, review ART treatment for any necessary changes to the regimen or dosage and move the client to the TB clinic for the duration of the TB treatment. For more information on the treatment of DR-TB/ HIV Co-infection refer to the current National Tuberculosis Control Programme Manual. Refer to Annex 11.16 for ART dose adjustments in paediatrics on TB treatment"),
 S("txt-p130-t0278", 130, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.1.5 TB Prevention > ART for TB patients (continued)", "ART for TB patients (continued)", ["0344"], "Key message: ART should be started as soon as TB treatment is tolerated, preferably within 2 weeks of initiating tuberculosis treatment, except for clients with TB meningitis", pages=[130, 131]),
 S("txt-p132-t0279", 132, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.1 Management of Clients with Advanced Immunodeficiency", "6.2.1 Management of Clients with Advanced Immunodeficiency", ["0345"], "Clients with advanced immunodeficiency are at high risk of opportunistic infections including TB, cryptococcal meningitis (CCM), toxoplasmosis, Pneumocystis Jirovecii Pneumonia (PJP), and other bacterial infections. Clients may also progress to advanced immunodeficiency (advanced HIV disease) while on treatment, if they are not on an effective regimen, adherence is not adequate or they develop resistance."),
 S("txt-p132-t0280", 132, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.1 Management of Clients with Advanced Immunodeficiency > Advanced HIV package of care", "Advanced HIV package of care", ["0346"], "A defined package of care interventions includes screening, treatment and prophylaxis for major opportunistic infections, rapid initiation of antiretroviral therapy (ART) and intensified treatment adherence support, for people presenting to care with advanced HIV disease to reduce HIV-associated morbidity and mortality."),
 S("txt-p133-t0281", 133, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.1 Management of Clients with Advanced Immunodeficiency > Advanced HIV package of care (continued)", "Advanced HIV package of care (continued)", ["0349"], "- Rapid ART initiation (within 7 days) is recommended to restore immune functioning and prevent further decline of CD4 cell count.\n- Immediate ART in clients newly diagnosed with cryptococcal meningitis is not recommended due to the risk of life-threatening immune reconstitution inflammatory syndrome (IRIS). ART may be deferred for 6 weeks in patients diagnosed with cryptococcal meningitis and starting antifungal treatment.\n- In TB-diagnosed clients, ART should be started within 2 weeks of starting TB treatment when the client can tolerate treatment.\n- After ART initiation, clients need to be monitored closely for the following:\n   - Adverse events\n   - Clinical response\n   - Development of IRIS\n   - Non-adherence to ART"),
 S("txt-p134-t0282", 134, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.2 Cryptococcal infection and meningitis", "6.2.2 Cryptococcal infection and meningitis", ["0350", "0352", "0354"], "Clients with cryptococcal infection may present with symptoms (symptomatic) or without symptoms (asymptomatic) of meningitis. Cryptococcal meningitis (CCM) has a high mortality rate. It is important to treat the cryptococcal infection before CNS involvement to reduce morbidity and mortality (pre-emptive treatment). Clients with symptoms of meningitis should be referred to a medical doctor for further management as soon as the condition is suspected. Symptomatic clients who have a positive blood CrAg result should receive lumber puncture (LP) if feasible and if there are no contraindications to LP. If CSF CrAg is positive, start treatment for cryptococcal meningitis. If CSF CrAg is negative or LP is not feasible, start pre-emptive treatment for cryptococcosis under close supervision while admitted. With the availability of a safer, single-dose liposomal amphotericin B regimen, symptomatic serum CrAg positive patients where LP is not feasible may be considered for CCM treatment."),
 S("txt-p134-t0283", 134, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.2 Cryptococcal infection and meningitis > Contraindications to LP", "Contraindications to LP", ["0351"], "- significant coagulopathy\n- suspected space-occupying lesion based on focal nervous system signs (excluding cranial nerve VI palsy) or recurrent seizures and, where possible, confirmed by computed tomography (CT scan).\n- major spinal deformity\n- patient refusal after fully informed consent was sought.\n- Infection around the site of LP\nKey message: Raised intracranial pressure does not contraindicate lumbar puncture in (suspected) cryptococcal meningitis"),
 S("txt-p138-t0284", 138, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.2 Cryptococcal infection and meningitis > Diagnosis and Management of Cryptococcal Meningitis (continued)", "Diagnosis and Management of Cryptococcal Meningitis (continued)", ["0360", "0362"], "- CSF India ink may be used if CSF CrAg is not available The gold standard test is a culture of cerebrospinal fluid for Cryptococcus neoformans, but its role in diagnosis is limited due to the long turnaround time. For clients with advanced immunodeficiency, a positive blood CrAg with signs and symptoms of meningitis is an indication of an urgent LP. An LP may be performed among all clients with positive blood CrAg regardless of signs and symptoms of meningitis, if feasible, to rule out cryptococcal meningitis.\nKey message: Routine use of adjunctive corticosteroid therapy during the induction phase is not recommended in treating HIV- associated cryptococcal meningitis among adults, adolescents and children."),
 S("txt-p138-t0285", 138, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.2 Cryptococcal infection and meningitis > Monitoring of CCM patients on treatment", "Monitoring of CCM patients on treatment", ["0361", "0363"], "Patients on cryptococcal meningitis treatment need close monitoring for identification of raised intracranial pressure, drug toxicity and adverse events.\nFlucytosine (5- FC) may accumulate in patients with renal impairment owing to poor excretion. Hence there’s a nee d for dose adjustment.", pages=[138, 139]),
 S("txt-p140-t0286", 140, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.2 Cryptococcal infection and meningitis > Monitoring of CCM patients on treatment (continued)", "Monitoring of CCM patients on treatment (continued)", ["0365"], "- 5-FC blood concentrations should be observed closely in these patients to monitor excretion – NOTE: Therapeutic Drug Monitoring is not offered in Eswatini"),
 S("txt-p140-t0287", 140, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.2 Cryptococcal infection and meningitis > Laboratory monitoring", "Laboratory monitoring", ["0366"], "The following table summarises the laboratory monitoring required during CCM."),
 S("txt-p140-t0288", 140, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.2 Cryptococcal infection and meningitis > Raised intracranial pressure (ICP)", "Raised intracranial pressure (ICP)", [], "Cerebrospinal fluid opening pressure ≥20 cm H2O\nKey message: ICP is the commonest cause of morbidity and mortality among CM patients.", pages=[140, 141]),
 S("txt-p141-t0289", 141, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.2 Cryptococcal infection and meningitis > Therapeutic lumbar puncture", "Therapeutic lumbar puncture", ["0368", "0369"], "- Drain 20 - 30ml volume per LP sufficient to reduce the CSF pressure to less than 20 cm H20 (or to 50% of the opening pressure)\n- Repeat frequently if persistence or recurrence of symptoms or signs, until the second day of being symptom-free\n- Measure CSF opening pressure where manometer available\n- Regularly and carefully monitor clinical symptoms and signs\nKey message: Routine use of adjunctive corticosteroid therapy during the induction phase is not recommended in treating HIV-associated Cryptococcal meningitis among adults, adolescents and children"),
 S("txt-p141-t0290", 141, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.3 Histoplasmosis", "6.2.3 Histoplasmosis", ["0370"], "Definition: Infection caused by a fungus, Histoplasma capsulatum. The fungus lives in the environment, especially in the soil and originates from bird or bat droppings. Infection occurs after inhaling the spores which settle in the lungs. In immunocompetent individuals, infection is often self-limiting, while among high-risk groups (immunosuppressed, elderly >55years, infants), severe infection may result from the dissemination of fungus from the lungs.\nSigns and symptoms of histoplasmosis: Fever\n- Cough\n- Fatigue (extreme tiredness)\n- Chills\n- Headache\n- Chest pain\n- Body aches"),
 S("txt-p141-t0291", 141, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.3 Histoplasmosis > Diagnosis", "Diagnosis", ["0371"], "- Disseminated histoplasmosis among PLHIV is diagnosed by molecular tests which detect circulating Histoplasma antigens in urine or blood. Antigen tests are highly sensitive (95%) and specific (99%). Culture and histological tests can also be used but their usefulness is limited by their complexities, variable performance, and long turnaround time.\n- The following populations should receive routine Histoplasma testing.\n   - All PLHIV (children> 5 years, adolescents and adults) with advanced HIV disease (CD4<200)\n   - All PLHIV with the above signs and symptoms suggestive of histoplasmosis"),
 S("txt-p142-t0292", 142, "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease > 6.2.3 Histoplasmosis > Histoplasmosis Treatment", "Histoplasmosis Treatment", ["0372"], "The table below highlights available treatment options for patients with Histoplasmosis"),
]
